import math
import cmath
import numpy as np
from numba import njit

@njit(cache=True)
def _hessenberg(A):
    n = A.shape[0]
    H = np.empty((n, n), dtype=np.complex128)
    for i in range(n):
        for j in range(n):
            H[i, j] = A[i, j]
    v = np.empty(n, dtype=np.complex128)
    for k in range(n - 2):
        s = 0.0
        for i in range(k + 1, n):
            z = H[i, k]
            s += z.real * z.real + z.imag * z.imag
        nx = math.sqrt(s)
        if nx == 0.0:
            continue
        x0 = H[k + 1, k]
        ax0 = abs(x0)
        if ax0 == 0.0:
            phase = 1.0 + 0.0j
        else:
            phase = x0 / ax0
        alpha = -phase * nx
        nv = 0.0
        for i in range(k + 1, n):
            v[i] = H[i, k]
        v[k + 1] -= alpha
        for i in range(k + 1, n):
            z = v[i]
            nv += z.real * z.real + z.imag * z.imag
        if nv < 1.0e-300:
            continue
        inv2 = 2.0 / nv
        for j in range(k, n):
            w = 0.0j
            for i in range(k + 1, n):
                w += np.conj(v[i]) * H[i, j]
            w *= inv2
            for i in range(k + 1, n):
                H[i, j] -= w * v[i]
        for i in range(n):
            w = 0.0j
            for j in range(k + 1, n):
                w += H[i, j] * v[j]
            w *= inv2
            for j in range(k + 1, n):
                H[i, j] -= w * np.conj(v[j])
        for i in range(k + 2, n):
            H[i, k] = 0.0
    return H


@njit(cache=True)
def _dominant_eigenvalue(A):
    H = _hessenberg(A)
    n = H.shape[0]
    m = n - 1
    it = 0
    maxit = 2000
    cc = np.empty(n, dtype=np.float64)
    ss = np.empty(n, dtype=np.complex128)
    while m > 0:
        if it > maxit:
            return 0.0j, False
        if abs(H[m, m - 1]) <= 1.0e-14 * (abs(H[m - 1, m - 1]) + abs(H[m, m])):
            H[m, m - 1] = 0.0
            m -= 1
            it = 0
            continue
        l = m
        while l > 0:
            if abs(H[l, l - 1]) <= 1.0e-14 * (abs(H[l - 1, l - 1]) + abs(H[l, l])):
                H[l, l - 1] = 0.0
                break
            l -= 1
        if m == l:
            m -= 1
            it = 0
            continue
        a = H[m - 1, m - 1]
        b = H[m - 1, m]
        c = H[m, m - 1]
        d = H[m, m]
        disc = cmath.sqrt((a - d) * (a - d) + 4.0 * b * c)
        mu1 = 0.5 * (a + d + disc)
        mu2 = 0.5 * (a + d - disc)
        if abs(mu1 - d) <= abs(mu2 - d):
            mu = mu1
        else:
            mu = mu2
        for i in range(l, m + 1):
            H[i, i] -= mu
        for k in range(l, m):
            a0 = H[k, k]
            b0 = H[k + 1, k]
            aa = abs(a0)
            bb = abs(b0)
            r = math.sqrt(aa * aa + bb * bb)
            if r == 0.0:
                c0 = 1.0
                s0 = 0.0j
            elif aa == 0.0:
                c0 = 0.0
                s0 = np.conj(b0) / bb
            else:
                c0 = aa / r
                s0 = a0 * np.conj(b0) / (aa * r)
            cc[k] = c0
            ss[k] = s0
            for j in range(k, m + 1):
                a1 = H[k, j]
                b1 = H[k + 1, j]
                H[k, j] = c0 * a1 + s0 * b1
                H[k + 1, j] = -np.conj(s0) * a1 + c0 * b1
        for k in range(l, m):
            c0 = cc[k]
            s0 = ss[k]
            for i in range(l, k + 2):
                a1 = H[i, k]
                b1 = H[i, k + 1]
                H[i, k] = c0 * a1 + np.conj(s0) * b1
                H[i, k + 1] = -s0 * a1 + c0 * b1
        for i in range(l, m + 1):
            H[i, i] += mu
        it += 1
    idx = 0
    best = abs(H[0, 0])
    for i in range(1, n):
        x = abs(H[i, i])
        if x > best:
            best = x
            idx = i
    return H[idx, idx], True


@njit(cache=True)
def _eigenvector_for(A, lam):
    n = A.shape[0]
    scale = 0.0
    for i in range(n):
        for j in range(n):
            z = A[i, j]
            if z < 0.0:
                z = -z
            if z > scale:
                scale = z
    shift = lam + 1.0e-13 * (scale + 1.0)
    M = np.empty((n, n), dtype=np.complex128)
    for i in range(n):
        for j in range(n):
            M[i, j] = A[i, j]
        M[i, i] -= shift
    piv = np.empty(n, dtype=np.int64)
    for k in range(n):
        p = k
        maxv = abs(M[k, k])
        for i in range(k + 1, n):
            v = abs(M[i, k])
            if v > maxv:
                maxv = v
                p = i
        piv[k] = p
        if p != k:
            for j in range(n):
                tmp = M[k, j]
                M[k, j] = M[p, j]
                M[p, j] = tmp
        for i in range(k + 1, n):
            f = M[i, k] / M[k, k]
            M[i, k] = f
            for j in range(k + 1, n):
                M[i, j] -= f * M[k, j]
    x = np.empty(n, dtype=np.complex128)
    for i in range(n):
        x[i] = 1.0 + 0.137 * i
    for k in range(n):
        p = piv[k]
        if p != k:
            tmp = x[k]
            x[k] = x[p]
            x[p] = tmp
    for i in range(n):
        s = x[i]
        for j in range(i):
            s -= M[i, j] * x[j]
        x[i] = s
    for i in range(n - 1, -1, -1):
        s = x[i]
        for j in range(i + 1, n):
            s -= M[i, j] * x[j]
        x[i] = s / M[i, i]
    nrm = 0.0
    for i in range(n):
        z = x[i]
        nrm += z.real * z.real + z.imag * z.imag
    nrm = math.sqrt(nrm)
    for i in range(n):
        x[i] /= nrm
    return x


@njit(cache=True)
def _refine(A, lam, x):
    n = A.shape[0]
    # Rayleigh quotient
    Ax = np.empty(n, dtype=np.complex128)
    for i in range(n):
        s = 0.0j
        for j in range(n):
            s += A[i, j] * x[j]
        Ax[i] = s
    num = 0.0j
    den = 0.0
    for i in range(n):
        num += np.conj(x[i]) * Ax[i]
        den += x[i].real * x[i].real + x[i].imag * x[i].imag
    lam2 = num / den
    r = 0.0
    for i in range(n):
        z = Ax[i] - lam2 * x[i]
        r += z.real * z.real + z.imag * z.imag
    return lam2, math.sqrt(r)


@njit(cache=True)
def solve(A):
    lam, ok = _dominant_eigenvalue(A)
    if not ok:
        return 0.0j, np.zeros(A.shape[0], dtype=np.complex128), False
    x = _eigenvector_for(A, lam)
    lam2, res = _refine(A, lam, x)
    return lam2, x, res < 1.0e-9
