import math
import numpy as np
from numba import njit
import numba_eig as _old

@njit(cache=True)
def _hessenberg(A):
    n = A.shape[0]
    H = np.empty((n, n), dtype=np.float64)
    for i in range(n):
        for j in range(n):
            H[i, j] = A[i, j]
    v = np.empty(n, dtype=np.float64)
    for k in range(n - 2):
        s = 0.0
        for i in range(k + 1, n):
            s += H[i, k] * H[i, k]
        nx = math.sqrt(s)
        if nx == 0.0:
            continue
        x0 = H[k + 1, k]
        if x0 >= 0.0:
            alpha = -nx
        else:
            alpha = nx
        nv = 0.0
        for i in range(k + 1, n):
            v[i] = H[i, k]
        v[k + 1] -= alpha
        for i in range(k + 1, n):
            nv += v[i] * v[i]
        if nv < 1.0e-300:
            continue
        inv2 = 2.0 / nv
        for j in range(k, n):
            w = 0.0
            for i in range(k + 1, n):
                w += v[i] * H[i, j]
            w *= inv2
            for i in range(k + 1, n):
                H[i, j] -= w * v[i]
        for i in range(n):
            w = 0.0
            for j in range(k + 1, n):
                w += H[i, j] * v[j]
            w *= inv2
            for j in range(k + 1, n):
                H[i, j] -= w * v[j]
        for i in range(k + 2, n):
            H[i, k] = 0.0
    return H


@njit(cache=True)
def _hqr(a):
    n = a.shape[0]
    wr = np.zeros(n, dtype=np.float64)
    wi = np.zeros(n, dtype=np.float64)
    anorm = 0.0
    for i in range(n):
        j0 = i - 1
        if j0 < 0:
            j0 = 0
        for j in range(j0, n):
            anorm += abs(a[i, j])
    nn = n - 1
    t = 0.0
    while nn >= 0:
        its = 0
        while True:
            l = nn
            while l >= 1:
                s = abs(a[l - 1, l - 1]) + abs(a[l, l])
                if s == 0.0:
                    s = anorm
                if abs(a[l, l - 1]) + s == s:
                    a[l, l - 1] = 0.0
                    break
                l -= 1
            x = a[nn, nn]
            if l == nn:
                wr[nn] = x + t
                wi[nn] = 0.0
                nn -= 1
            else:
                y = a[nn - 1, nn - 1]
                w = a[nn, nn - 1] * a[nn - 1, nn]
                if l == nn - 1:
                    p = 0.5 * (y - x)
                    q = p * p + w
                    z = math.sqrt(abs(q))
                    x += t
                    if q >= 0.0:
                        if z >= 0.0:
                            z = p + z
                        else:
                            z = p - z
                        wr[nn - 1] = x + z
                        wr[nn] = x + z
                        if z != 0.0:
                            wr[nn] = x - w / z
                        wi[nn - 1] = 0.0
                        wi[nn] = 0.0
                    else:
                        wr[nn - 1] = x + p
                        wr[nn] = x + p
                        wi[nn - 1] = -z
                        wi[nn] = z
                    nn -= 2
                else:
                    if its == 60:
                        return wr, wi, False
                    if its == 10 or its == 20:
                        t += x
                        for i in range(nn + 1):
                            a[i, i] -= x
                        s = abs(a[nn, nn - 1]) + abs(a[nn - 1, nn - 2])
                        y = 0.75 * s
                        x = y
                        w = -0.4375 * s * s
                    its += 1
                    m = nn - 2
