                        r = x - z
                        s = y - z
                        p = (r * s - w) / a[m + 1, m] + a[m, m + 1]
                        q = a[m + 1, m + 1] - z - r - s
                        r = a[m + 2, m + 1]
                        s = abs(p) + abs(q) + abs(r)
                        p /= s
                        q /= s
                        r /= s
                        if m == l:
                            break
                        u = abs(a[m, m - 1]) * (abs(q) + abs(r))
                        v = abs(p) * (abs(a[m - 1, m - 1]) + abs(z) + abs(a[m + 1, m + 1]))
                        if u + v == v:
                            break
                        m -= 1
                    for i in range(m + 2, nn + 1):
                        a[i, i - 2] = 0.0
                        if i != m + 2:
                            a[i, i - 3] = 0.0
                    for k in range(m, nn):
                        if k != m:
                            p = a[k, k - 1]
                            q = a[k + 1, k - 1]
                            r = 0.0
                            if k != nn - 1:
                                r = a[k + 2, k - 1]
                            x = abs(p) + abs(q) + abs(r)
                            if x != 0.0:
                                p /= x
                                q /= x
                                r /= x
                        s = math.sqrt(p * p + q * q + r * r)
                        if p < 0.0:
                            s = -s
                        if s != 0.0:
                            if k == m:
                                if l != m:
                                    a[k, k - 1] = -a[k, k - 1]
                            else:
                                a[k, k - 1] = -s * x
                            p += s
                            x = p / s
                            y = q / s
                            z = r / s
                            q /= p
                            r /= p
                            for j in range(k, nn + 1):
                                p = a[k, j] + q * a[k + 1, j]
                                if k != nn - 1:
                                    p += r * a[k + 2, j]
                                    a[k + 2, j] -= p * z
                                a[k + 1, j] -= p * y
                                a[k, j] -= p * x
                            mmin = k + 3
                            if nn < mmin:
                                mmin = nn
                            for i in range(l, mmin + 1):
                                p = x * a[i, k] + y * a[i, k + 1]
                                if k != nn - 1:
                                    p += z * a[i, k + 2]
                                    a[i, k + 2] -= p * r
                                a[i, k + 1] -= p * q
                                a[i, k] -= p
            if not (l < nn - 1):
                break
    return wr, wi, True


@njit(cache=True)
def _dominant_eigenvalue(A):
    H = _hessenberg(A)
    wr, wi, ok = _hqr(H)
    if not ok:
        return 0.0j, False
    idx = 0
    best = wr[0] * wr[0] + wi[0] * wi[0]
    for i in range(1, wr.shape[0]):
        v = wr[i] * wr[i] + wi[i] * wi[i]
        if v > best:
            best = v
            idx = i
    return wr[idx] + 1j * wi[idx], True


@njit(cache=True)
def solve(A):
    lam, ok = _dominant_eigenvalue(A)
    if not ok:
        return 0.0j, np.zeros(A.shape[0], dtype=np.complex128), False
    x = _old._eigenvector_for(A, lam)
    lam2, res = _old._refine(A, lam, x)
    return lam2, x, res < 1.0e-9
